    auto& smpl=root.find("smpl")->data;smpl.resize(86,0);put32(smpl,28,2);put32(smpl,32,2);for(size_t i=0;i<2;++i){const auto p=36+i*24;put32(smpl,p,21+static_cast<unsigned>(i));put32(smpl,p+4,1);put32(smpl,p+8,4);put32(smpl,p+12,i?7:10);put32(smpl,p+16,0x80000000u);put32(smpl,p+20,3);}smpl[84]=0xb1;smpl[85]=0xb2;
    const auto sourcePcm=pcm;Chunk fact;fact.id="fact";fact.data={16,0,0,0,0xc1};fact.padding=0xe2;root.children.push_back(fact);Chunk opaque;opaque.id="zzzz";opaque.data={1,2,3};opaque.padding=0xa5;root.children.push_back(opaque);
