    require(doc.erase_pcm(4,8)&&doc.format().frames==12,"PCM delete closes selected frame gap");auto expected=root;auto& e=expected.find("data")->data;e.erase(e.begin()+16,e.begin()+32);auto& ec=expected.find("cue ")->data;put32(ec,32,8);put32(ec,48,8);put32(expected.find("LIST","adtl")->children[0].data,4,6);auto& ew=expected.find("wsmp")->data;ew.erase(ew.begin()+36,ew.begin()+52);put32(ew,16,1);put32(ew,32,6);auto& es=expected.find("smpl")->data;es.erase(es.begin()+60,es.begin()+84);put32(es,28,1);put32(es,48,6);put32(expected.find("fact")->data,0,12);const auto deleted=doc.save_bytes();require(deleted==expected.encode(),"PCM delete maps cues labelled lengths WSMP half-open SMPL inclusive loops and fact; tails unknown identity padding exact");
    require(doc.undo()&&doc.save_bytes()==before&&!doc.dirty(),"PCM deletion is one complete reversible transaction");require(!doc.erase_pcm(4,4)&&doc.save_bytes()==before,"Empty PCM deletion is no-op");rejected([&]{doc.erase_pcm(8,4);},"Reversed PCM range rejected");rejected([&]{doc.erase_pcm(0,17);},"Out-of-bounds PCM range rejected");rejected([&]{doc.copy_pcm(0,17);},"Invalid PCM copy rejected");require(doc.redo()&&doc.save_bytes()==deleted,"Invalid PCM requests retain pending Redo");
